from pathlib import Path
import json,hashlib,zipfile,io,subprocess,sys
r=Path(__file__).resolve().parent.parent/'desktop/runtime/presets';r.mkdir(parents=True,exist_ok=True);up=Path(sys.argv[1]).resolve();commit=subprocess.check_output(['git','-C',str(up),'rev-parse','HEAD']).decode().strip();assert commit=='2ce8aa15d05bd57213e6f746f953aafb7ded7a8b','Unexpected upstream commit';items=[]
def item(id,title,category,description,files,source,license):
 import base64
 b=io.BytesIO()
 with zipfile.ZipFile(b,'w',zipfile.ZIP_DEFLATED) as z:
  for name,data in sorted(files.items()):
   i=zipfile.ZipInfo(name,(2026,10,26,0,0,0));i.compress_type=zipfile.ZIP_DEFLATED;i.external_attr=0o100644<<16;z.writestr(i,data)
 data=b.getvalue();items.append(dict(id=id,title=title,category=category,description=description,source=source,license=license,archiveBase64=base64.b64encode(data).decode(),sha256=hashlib.sha256(data).hexdigest(),files=[{'path':n,'sha256':hashlib.sha256(d).hexdigest()} for n,d in sorted(files.items())]))
